#!/usr/bin/env python3
import sys
sys.path.insert(0, '/tmp')
from pdparse import parse, all_canvases

text = open('/home/vboxuser/rev-analysis/work/hidden_patch.pd', encoding='latin1').read()
root = parse(text)
cvs = all_canvases(root)
byid = {c.cid: c for c in cvs}

def cvname(c):
    return getattr(c, 'restore_name', None) or c.name or '?'

def dump_canvas(c, maxt=90):
    print(f'=== canvas cid#{c.cid} name={cvname(c)}  objs={len(c.objs)} conns={len(c.conns)} ===')
    for (gi, kind, txt, rec) in c.objs:
        print(f'  [{gi}] {kind}: {txt[:maxt]}')
    print('  --- connects (src,out)->(dst,in) ---')
    # compact
    for (s,o,d,i) in c.conns:
        print(f'  {s}:{o} -> {d}:{i}')

def find(term):
    res=[]
    for c in cvs:
        for (gi, kind, txt, rec) in c.objs:
            if term in txt:
                res.append((c,gi,kind,txt))
    return res

cmd = sys.argv[1] if len(sys.argv)>1 else 'root'
if cmd=='root':
    dump_canvas(root)
elif cmd=='cid':
    dump_canvas(byid[int(sys.argv[2])], maxt=int(sys.argv[3]) if len(sys.argv)>3 else 90)
elif cmd=='find':
    for c,gi,kind,txt in find(sys.argv[2]):
        print(f'cid#{c.cid}[{cvname(c)}] [{gi}] {kind}: {txt[:100]}')
elif cmd=='tree':
    def rec(c, depth):
        print('  '*depth + f'cid#{c.cid} {cvname(c)} (objs {len(c.objs)})')
        for ch in c.children:
            rec(ch, depth+1)
    rec(root,0)

