#!/usr/bin/env python3
import socket, time, sys

HOST, PORT = '127.0.0.1', 4562

def recv_for(s, total_t, idle_t=3.0):
    s.setblocking(False)
    buf = b''
    start = time.time()
    last = time.time()
    while time.time() - start < total_t:
        try:
            d = s.recv(4096)
            if d:
                buf += d
                last = time.time()
            else:
                break
        except BlockingIOError:
            if time.time() - last > idle_t and buf:
                break
            time.sleep(0.05)
        except Exception as e:
            print('recv err', e); break
    return buf

s = socket.create_connection((HOST, PORT), timeout=10)
print('connected, waiting up to 25s for banner...')
b = recv_for(s, 25, idle_t=4.0)
print('BANNER bytes=%d:' % len(b))
print(repr(b))
# try sending HELP
if len(sys.argv) > 1:
    for cmd in sys.argv[1:]:
        print('>>> sending', repr(cmd))
        s.sendall(cmd.encode('latin1') + b'\n')
        r = recv_for(s, 25, idle_t=5.0)
        print('  <<< %d bytes:' % len(r), repr(r))
s.close()

